export function componentAttrs (componentName, {componentCustomisation: {modifiers} = {}}) {
    if (!Array.isArray(modifiers)) modifiers = [];
    modifiers = modifiers.filter(Boolean);

    return [
        `data-component="${componentName}"`,
        (
            modifiers.length ?
            `data-cc="${modifiers.join('|')}"`
            : ''
        )
    ]
    .filter(Boolean)
    .join(' ')
};

export function mergeDefaultModifiers(data = {}, modifiers = []) {
    data.componentCustomisation = {
        ...(data.componentCustomisation || {}),
        modifiers: [
            ...(data?.componentCustomisation?.modifiers ?? []),
            modifiers
        ]
    };
    return data;
}